// Renders funcmap.json (generated by site/tools/funcmap) as a searchable, linked code map.
const GH = "https://github.com/ysinghc/snowflake-lite/blob/main/";
const root = document.getElementById("cm-root");
const q = document.getElementById("cm-q"), sel = document.getElementById("cm-pkg"), exp = document.getElementById("cm-exp");
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
let data, byId = {};

const label = (id) => id.replace(/^[^.]+\./, "");
const chip = (id) => byId[id] ? `<a class="chip" href="#${id}" data-go="${id}" title="${esc(id.split(".")[0])}">${esc(label(id))}</a>` : "";

function render() {
  const term = q.value.trim().toLowerCase();
  let shown = 0, html = "";
  for (const p of data.packages) {
    if (sel.value && p.dir !== sel.value) continue;
    let ph = "", file = "";
    for (const f of p.funcs) {
      if (exp.checked && !f.exported) continue;
      if (term && !(f.name + " " + (f.recv || "") + " " + (f.doc || "")).toLowerCase().includes(term)) continue;
      if (f.file !== file) { file = f.file; ph += `<div class="cm-file">${esc(file)}</div>`; }
      shown++;
      const calls = (f.calls || []).map(chip).join("") || '<span class="mute">nothing in this module</span>';
      const by = (f.calledBy || []).map(chip).join("") || '<span class="mute">nothing in this module (entry point, handler or exported API)</span>';
      ph += `<details class="fn" id="${f.id}"><summary><span class="sig">${f.recv ? `<span class="rc">(${esc(f.recv)})</span> ` : ""}${esc(f.sig)}</span>` +
        `<span class="pill${f.exported ? "" : " in"}">${f.exported ? "exported" : "internal"}</span>` +
        (f.doc ? `<span class="d">${esc(f.doc)}</span>` : "") + `</summary><div class="body">` +
        `<h5>Calls</h5>${calls}<h5>Called by</h5>${by}<h5>Source</h5><a href="${GH}${f.file}#L${f.line}">${esc(f.file)}:${f.line}</a></div></details>`;
    }
    if (ph) html += `<h3 class="cm-pkg"><code>${esc(p.path.replace(data.module + "/", ""))}</code></h3>${p.doc ? `<p class="mute">${esc(p.doc)}</p>` : ""}${ph}`;
  }
  root.innerHTML = html || '<p class="mute">No functions match.</p>';
  document.getElementById("cm-count").textContent = `${shown} functions`;
}

root.addEventListener("click", (e) => {
  const a = e.target.closest("[data-go]");
  if (!a) return;
  e.preventDefault();
  q.value = ""; exp.checked = false; sel.value = ""; render();
  const el = document.getElementById(a.dataset.go);
  if (el) { el.open = true; el.scrollIntoView({ block: "center" }); history.replaceState(null, "", "#" + a.dataset.go); }
});

fetch("/funcmap.json").then((r) => r.json()).then((d) => {
  data = d;
  for (const p of d.packages) { for (const f of p.funcs) byId[f.id] = f; sel.append(new Option(p.dir, p.dir)); }
  [q, sel, exp].forEach((el) => el.addEventListener("input", render));
  render();
  const h = decodeURIComponent(location.hash.slice(1));
  if (h && document.getElementById(h)) { document.getElementById(h).open = true; document.getElementById(h).scrollIntoView(); }
}).catch(() => (root.innerHTML = '<p class="mute">Could not load the code map.</p>'));
